from fastapi import APIRouter, Depends, HTTPException, status
from pydantic import BaseModel
import hvac

router = APIRouter(prefix="/pki")

class CertificateIssueRequest(BaseModel):
    role_name: str
    common_name: str
    ttl: str = "720h"

@router.post("/issue-certificate")
async def issue_tls_certificate(
    req: CertificateIssueRequest,
    domain_verifier: DomainVerificationService = Depends(get_domain_verifier),
    vault_client: hvac.Client = Depends(get_vault_client),
    user: User = Depends(get_current_user)
):
    if not await domain_verifier.is_domain_verified_for_org(domain=req.common_name, org_id=user.organization_id):
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Cannot issue certificate for unverified domain")

    try:
        cert_data = vault_client.secrets.pki.generate_certificate(
            name=req.role_name,
            common_name=req.common_name,
            extra_params={"ttl": req.ttl}
        )
        return {
            "certificate": cert_data["data"]["certificate"],
            "private_key": cert_data["data"]["private_key"],
            "ca_chain": cert_data["data"]["ca_chain"]
        }
    except hvac.exceptions.VaultError as err:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=f"PKI error: {err}")
